def _insert(s:Storage,test:int):
 for pos,(text,kind,key,opts) in enumerate(Q,1):
  q=s.db.execute('INSERT INTO questions(test_id,position,text,kind,required,identity_key) VALUES(?,?,?,?,?,?)',(test,pos,text,kind,1,key)).lastrowid
  for n,opt in enumerate(opts,1): s.db.execute('INSERT INTO options(question_id,position,text,action_json) VALUES(?,?,?,?)',(q,n,opt,json.dumps({'type':'move_stage'}) if text==SPECIAL_QUESTION and opt==SPECIAL_ANSWER else None))

def seed_default_test(s:Storage):
 test=s._one('SELECT * FROM tests WHERE name=?',(TEST_NAME,))
 if test:
  cnt=s._one('SELECT count(*) FROM questions WHERE test_id=?',(test['id'],))[0]; attempts=s._one('SELECT count(*) FROM attempts WHERE test_id=?',(test['id'],))[0]
  # Upgrade the previous seed as well as the earlier wrong single-choice 18/19.
  old_types=[r['kind'] for r in s.test_questions(test['id'])]
  if cnt==len(Q) and old_types[17:19]==['multi_choice','multi_choice']:
   with s.db:s.db.execute('UPDATE options SET action_json=? WHERE text=?',(json.dumps({'type':'move_stage','pipeline':'HH-юристы','status':'готов к сотрудничеству'},ensure_ascii=False),SPECIAL_ANSWER))
   return
  if attempts:return
  with s.db:s.db.execute('DELETE FROM questions WHERE test_id=?',(test['id'],));_insert(s,test['id'])
  return
 with s.db:
  test=s.db.execute('INSERT INTO tests(name,enabled,created_at) VALUES(?,?,?)',(TEST_NAME,1,int(time.time()))).lastrowid;_insert(s,test)
